SELECT *, AVG(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_amount, MAX(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_amount, COUNT(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_amount FROM transactions
